<h1 class="page-title">Thông tin thanh toán</h1><form action="/checkout" method="post"><input type="hidden" name="checkout_token" value="<?= e($_SESSION['checkout_token']) ?>"><?= App\Core\Csrf::field() ?><div class="row"><div class="col-lg-7"><section class="panel"><h2>Địa chỉ giao hàng</h2><label class="form-label" for="checkout-address">Chọn địa chỉ đã lưu hoặc nhập mới bên dưới</label><select class="form-select" name="address_id" id="checkout-address"><option value="">Nhập địa chỉ mới</option><?php foreach($addresses as $a):?><option value="<?= $a['id'] ?>" <?= $a['is_default']?'selected':'' ?>><?= e($a['recipient'].' · '.$a['address_line']) ?></option><?php endforeach?></select><label class="form-label" for="checkout-recipient">Người nhận</label><input class="form-control" name="recipient" id="checkout-recipient" value="<?= e($user['name']) ?>"><label class="form-label" for="checkout-phone">Số điện thoại</label><input class="form-control" name="phone" id="checkout-phone" value="<?= e($user['phone']) ?>"><label class="form-label" for="checkout-line">Địa chỉ đầy đủ</label><textarea class="form-control" name="address_line" id="checkout-line" maxlength="500"></textarea><label class="form-label" for="checkout-note">Ghi chú giao hàng</label><textarea class="form-control" name="note" id="checkout-note" maxlength="1000"></textarea></section><section class="panel"><h2>Phương thức thanh toán</h2><label class="d-block py-2"><input type="radio" name="payment_method" value="cod" checked> Thanh toán khi nhận hàng (COD)</label><label class="d-block py-2"><input type="radio" name="payment_method" value="bank_transfer"> Chuyển khoản ngân hàng</label><p class="muted small mt-2">Với chuyển khoản, nhân viên sẽ xác nhận thông tin thanh toán qua thông tin liên hệ trên đơn. Không tự động thu tiền.</p></section></div><div class="col-lg-5"><section class="panel"><h2>Đơn hàng của bạn</h2><?php foreach($items as $p):?><div class="d-flex justify-content-between gap-3 border-bottom py-3"><span><?= e($p['name']) ?> × <?= $p['quantity'] ?></span><b class="text-nowrap"><?= money($p['subtotal']) ?></b></div><?php endforeach?><div class="d-flex justify-content-between my-4"><b>Tổng thanh toán</b><strong><?= money($total) ?></strong></div><p class="muted small">Giá và tồn kho được kiểm tra lại khi xác nhận đặt hàng.</p><button id="place-order" class="btn btn-primary w-100" type="submit">Xác nhận đặt hàng</button></section></div></div></form>
